export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"id","term":"Coin vs token","aka":["koin vs token","perbedaan coin dan token"],"short":"Coin adalah aset asli sebuah blockchain yang dipakai untuk membayar biaya jaringan, sedangkan token adalah aset yang dibuat di atas blockchain lain melalui smart contract.","body":[["Contoh coin adalah ",["BTC","bitcoin"]," di jaringan Bitcoin, ",["ETH","ethereum"]," di Ethereum, dan SOL di Solana. Coin dipakai untuk membayar biaya transaksi dan sering juga untuk ",["staking","staking"]," demi keamanan jaringan. Tanpa coin asli, jaringan itu tidak bisa berjalan."],["Token tidak punya ",["blockchain","blockchain"]," sendiri. Ia dibuat dengan ",["smart contract","smart-contract"]," mengikuti standar tertentu, misalnya ERC-20 di Ethereum atau SPL di Solana. ",["USDT","usdt"],", UNI, dan banyak token governance adalah contoh token. Satu token yang sama bisa ada di beberapa jaringan, misalnya USDT di Ethereum, TRON, dan BNB Chain."],"Perbedaan ini penting secara praktis. Untuk memindahkan token, Anda tetap membutuhkan coin asli jaringan tersebut untuk membayar gas. Selain itu, saat deposit atau tarik, Anda harus memilih jaringan yang tepat agar token sampai ke alamat yang benar."],"example":"Misalkan Anda memiliki 200 USDT versi ERC-20 di dompet, tetapi saldo ETH Anda 0. Saat Anda mencoba mengirim USDT itu, transaksi gagal karena tidak ada ETH untuk membayar gas. Setelah Anda menambahkan 0,005 ETH, transfer berhasil dengan biaya misalnya 0,0008 ETH, dan sisa 0,0042 ETH tetap di dompet untuk transaksi berikutnya.","mistakes":["Menganggap token dan coin bisa dipindahkan tanpa coin asli jaringan untuk biaya gas.","Memilih jaringan yang salah saat menarik token, misalnya BEP20 padahal alamat tujuan hanya mendukung ERC-20.","Mengira semua token yang namanya mirip adalah aset resmi, padahal siapa pun bisa membuat token dengan nama yang sama."],"faq":[{"q":"Apakah USDT itu coin atau token?","a":"USDT adalah token. Ia diterbitkan oleh Tether di atas beberapa blockchain, seperti Ethereum dan TRON, dan tidak punya blockchain sendiri."},{"q":"Bagaimana cara mengecek token asli?","a":"Cocokkan alamat kontrak token dengan sumber resmi proyek atau block explorer. Nama dan simbol saja tidak cukup karena mudah ditiru."}],"title":"Coin vs token: apa bedanya di kripto?","description":"Pahami perbedaan coin dan token di kripto, kenapa Anda butuh coin asli untuk gas, dan cara memilih jaringan yang tepat.","related":[["layer-1","Layer 1 (L1)","Layer 1 (L1) adalah blockchain dasar yang memproses dan memfinalisasi transaksinya sendiri dengan mekanisme konsensus dan koin aslinya, seperti Bitcoin, Ethereum, dan Solana."],["smart-contract","Smart contract","Smart contract adalah program yang disimpan dan dijalankan di blockchain, yang otomatis mengeksekusi aturan tertentu ketika syaratnya terpenuhi, tanpa perlu perantara."],["governance-token","Governance token (token tata kelola)","Governance token adalah token yang memberi pemegangnya hak suara atas keputusan sebuah protokol atau DAO, seperti perubahan parameter, penggunaan kas, atau peningkatan kontrak."],["tokenomics","Tokenomics","Tokenomics adalah desain ekonomi sebuah token, mencakup jumlah suplai, cara distribusi, jadwal unlock, kegunaan token, dan mekanisme yang menambah atau mengurangi suplai."],["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"id","term":"Memecoin (koin meme)","aka":["meme coin","koin meme"],"short":"Memecoin adalah aset kripto yang nilainya terutama digerakkan oleh budaya internet, komunitas, dan tren media sosial, bukan oleh kegunaan teknis atau pendapatan proyek.","body":["Dogecoin, yang lahir pada 2013 dari meme anjing Shiba Inu, adalah memecoin pertama yang terkenal. Setelah itu muncul Shiba Inu, PEPE, dan ribuan token lain. Banyak memecoin baru diluncurkan di Solana atau BNB Chain lewat platform peluncuran yang memungkinkan siapa pun membuat token dalam hitungan menit.",["Harga memecoin sangat volatil. Kenaikan ratusan persen dan penurunan lebih dari 90% bisa terjadi dalam waktu singkat. ",["Likuiditas","liquidity"]," token baru sering tipis, sehingga order besar menyebabkan ",["slippage","slippage"]," tinggi, dan sebagian besar suplai kadang dipegang segelintir dompet."],["Risiko ",["rug pull","rug-pull"]," juga tinggi pada memecoin kecil. Sebelum membeli, periksa apakah likuiditas dikunci, berapa persen suplai dipegang dompet teratas, dan apakah kontraknya memiliki fungsi mencetak token baru atau memblokir penjualan."]],"example":["Misalkan Anda membeli memecoin senilai 100 ",["USDT","usdt"],". Dalam dua hari harganya naik 300%, sehingga nilainya menjadi 400 USDT. Seminggu kemudian harganya turun 80% dari puncak, sehingga nilainya tinggal 80 USDT. Artinya Anda rugi 20 USDT dari modal awal meski sempat untung 300 USDT di atas kertas. Pergerakan sebesar ini cukup umum pada memecoin."],"mistakes":["Membeli memecoin karena ramai di media sosial tanpa memeriksa distribusi pemegang dan likuiditasnya.","Memakai dana besar atau leverage pada aset yang bisa turun 90% dalam hitungan hari.","Membeli token dengan nama sama dari alamat kontrak yang salah."],"faq":[{"q":"Apakah memecoin punya nilai fundamental?","a":"Sebagian besar memecoin tidak punya pendapatan atau kegunaan teknis yang berarti. Nilainya bergantung pada perhatian komunitas, yang bisa berubah sangat cepat."},{"q":"Apa contoh memecoin terkenal?","a":"Contoh yang dikenal luas adalah Dogecoin, Shiba Inu, dan PEPE. Popularitas mereka tidak menjamin memecoin baru akan mengikuti jalur yang sama."}],"title":"Apa itu memecoin? Arti koin meme dan risikonya","description":"Pahami arti memecoin, kenapa harganya sangat bergejolak, dan apa yang perlu dicek untuk menghindari rug pull.","related":[["altcoin","Altcoin","Altcoin adalah sebutan untuk semua aset kripto selain Bitcoin, mulai dari jaringan besar seperti Ethereum dan Solana hingga token kecil yang baru diluncurkan."],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."],["liquidity","Likuiditas (liquidity)","Likuiditas adalah seberapa mudah dan cepat sebuah aset kripto bisa dibeli atau dijual dalam jumlah besar tanpa menggeser harganya secara signifikan."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"id","term":"HODL","aka":["hold","holding","hold on for dear life"],"short":"HODL adalah istilah kripto untuk strategi menyimpan aset dalam jangka panjang tanpa terpengaruh naik turunnya harga harian.","body":[["Istilah ini berasal dari salah ketik kata hold di sebuah forum ",["Bitcoin","bitcoin"]," pada 2013, lalu menjadi meme. Belakangan orang menafsirkannya sebagai singkatan hold on for dear life. Pemegang jangka panjang sering disebut holder atau hodler."],["Strategi HODL mengurangi godaan trading berlebihan, menghemat biaya transaksi, dan menghindari kesalahan karena emosi. Banyak hodler membeli bertahap dengan dollar cost averaging dan menyimpan aset di ",["dompet pribadi","non-custodial-wallet"]," atau ",["cold wallet","cold-wallet"],"."],["Namun HODL bukan berarti tidak pernah meninjau ulang. Menyimpan Bitcoin berbeda dengan menyimpan ",["altcoin","altcoin"]," kecil yang proyeknya bisa ditinggalkan. Anda tetap perlu tahu alasan memegang aset, berapa porsi yang wajar, dan bagaimana mengamankan ",["seed phrase","seed-phrase"],"."]],"example":["Misalkan Anda membeli 0,02 BTC di harga 40.000 ",["USDT","usdt"],", total 800 USDT. Dalam setahun harga sempat turun ke 25.000 USDT, sehingga nilai Anda tinggal 500 USDT, turun 37,5%. Jika Anda tetap memegang dan harga kemudian berada di 60.000 USDT, nilai 0,02 BTC menjadi 1.200 USDT. Hasil ini hanya dinikmati jika Anda sanggup menahan penurunan di tengah jalan tanpa terpaksa menjual."],"mistakes":["Memegang altcoin apa saja selamanya tanpa memeriksa apakah proyeknya masih berjalan.","Memakai dana yang mungkin dibutuhkan dalam waktu dekat, sehingga terpaksa menjual saat harga sedang turun.","Menyimpan aset jangka panjang di exchange tanpa memahami risiko kustodian."],"faq":[{"q":"Apa arti HODL?","a":"HODL berarti menyimpan aset kripto jangka panjang dan tidak menjualnya karena fluktuasi harga. Istilah ini berasal dari salah ketik kata hold."},{"q":"Apakah HODL selalu menguntungkan?","a":"Tidak. Hasilnya tergantung aset yang dipegang dan harga saat Anda membeli serta menjual. Beberapa koin tidak pernah kembali ke harga puncaknya."}],"title":"Apa itu HODL? Arti strategi hold di kripto","description":"Arti HODL di kripto, asal-usul istilahnya, kelebihan strategi menyimpan jangka panjang, dan kesalahan yang perlu dihindari.","related":[["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) adalah strategi membeli aset dengan nominal tetap secara berkala, misalnya setiap minggu atau bulan, tanpa memedulikan harga saat itu."],["cold-wallet","Cold wallet (cold storage)","Cold wallet adalah cara menyimpan kripto dengan private key yang dibuat dan disimpan sepenuhnya offline, sehingga tidak bisa dijangkau peretas lewat internet."],["bear-market","Bear market (pasar bearish)","Bear market adalah periode ketika harga aset di pasar cenderung turun secara berkelanjutan, biasanya 20% atau lebih dari puncaknya, disertai sentimen pesimis dan volume yang menurun."],["volatility","Volatility (volatilitas)","Volatilitas adalah ukuran seberapa besar dan seberapa cepat harga sebuah aset bergerak naik turun dalam periode tertentu."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"id","term":"Liquidity pool (kolam likuiditas)","aka":["LP","kolam likuiditas","pool likuiditas","pool"],"short":"Liquidity pool adalah kumpulan token yang dikunci dalam smart contract, biasanya berpasangan, untuk melayani swap di DEX atau pinjaman di protokol DeFi.","body":[["Siapa pun bisa menjadi ",["penyedia likuiditas","market-maker"]," dengan menyetor pasangan token ke pool, misalnya ",["ETH","ethereum"]," dan ",["USDC","usdc"]," dengan nilai seimbang. Sebagai ",["bukti kepemilikan","proof-of-stake"],", Anda menerima LP token atau posisi ",["NFT","nft"]," yang mewakili porsi Anda di pool."],["Imbalannya berasal dari fee swap yang dibagi sesuai porsi Anda, kadang ditambah insentif token dari protokol. Saat menarik ",["likuiditas","liquidity"],", Anda menerima kembali bagian dari kedua token sesuai komposisi pool saat itu, yang bisa berbeda dari komposisi saat Anda menyetor."],"Risiko utamanya ada tiga. Pertama impermanent loss saat harga kedua token bergerak berbeda. Kedua risiko smart contract jika protokol diretas. Ketiga, pada token baru, risiko rug pull jika pembuat token menarik likuiditas. Ukuran pool juga penting bagi trader: pool kecil berarti price impact besar."],"example":"Misalnya sebuah pool ETH/USDC bernilai total 1.000.000 USD dan Anda menyetor senilai 10.000 USD, sehingga porsi Anda 1%. Pada hari tertentu volume swap 500.000 USD dengan fee pool 0,3%, menghasilkan fee 1.500 USD. Bagian Anda 1%, yaitu 15 USD untuk hari itu. Volume berubah setiap hari, dan hasil ini belum memperhitungkan kemungkinan impermanent loss jika harga ETH bergerak jauh.","mistakes":["Menghitung keuntungan hanya dari fee tanpa membandingkannya dengan menyimpan token biasa.","Menyetor ke pool token baru tanpa memeriksa apakah likuiditas pembuatnya dikunci.","Menghilangkan atau mentransfer LP token tanpa sadar bahwa itu adalah bukti hak atas dana di pool."],"faq":[{"q":"Dari mana keuntungan liquidity pool berasal?","a":"Terutama dari fee swap yang dibayar trader, dan kadang dari insentif token tambahan yang diberikan protokol."},{"q":"Apakah dana di liquidity pool bisa ditarik kapan saja?","a":"Pada kebanyakan DEX bisa, dengan membayar biaya gas. Namun jika Anda juga melakukan staking LP token di program farming, mungkin ada aturan penguncian tersendiri."}],"title":"Apa itu liquidity pool? Arti kolam likuiditas DeFi","description":"Pelajari arti liquidity pool, cara menjadi penyedia likuiditas, sumber imbal hasilnya, dan risiko seperti impermanent loss.","related":[["amm","AMM (automated market maker)","AMM adalah mekanisme di DEX yang menentukan harga secara otomatis berdasarkan rumus dan isi liquidity pool, sehingga Anda bisa swap tanpa menunggu pembeli atau penjual lain."],["impermanent-loss","Impermanent loss (kerugian tidak permanen)","Impermanent loss adalah selisih nilai antara menyetor token ke liquidity pool dan sekadar menyimpannya di dompet, yang muncul ketika harga kedua token di pool bergerak berbeda."],["yield-farming","Yield farming","Yield farming adalah strategi menempatkan aset kripto di berbagai protokol DeFi, seperti liquidity pool atau lending, untuk mendapatkan fee, bunga, dan token insentif."],["rug-pull","Rug pull","Rug pull adalah penipuan di mana pengembang proyek kripto tiba-tiba menarik likuiditas, menjual token dalam jumlah besar, atau menyalahgunakan kontrak, sehingga harga token anjlok dan investor tidak bisa keluar."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"id","term":"Perp DEX (perpetual on-chain)","aka":["perpetual DEX","DEX perpetual","on-chain perpetuals"],"short":"Perp DEX adalah decentralized exchange yang menyediakan kontrak berjangka perpetual dengan leverage, di mana margin dan penyelesaian posisi dikelola smart contract atau blockchain, bukan oleh exchange terpusat.","body":[["Hyperliquid adalah contoh perp ",["DEX","dex"]," yang berjalan di ",["blockchain","blockchain"],"-nya sendiri dengan ",["order book","order-book"]," on-chain. Ada juga dYdX, GMX, dan lainnya dengan desain berbeda, misalnya model ",["pool likuiditas","liquidity-pool"]," atau order book. Anda menyetor margin, biasanya ",["USDC","usdc"],", dari ",["dompet non-kustodian","non-custodial-wallet"]," lalu membuka posisi long atau short dengan leverage."],"Mekanismenya mirip kontrak perpetual di exchange terpusat: ada mark price, funding rate, margin pemeliharaan, dan likuidasi. Perbedaannya ada pada detail. Beberapa perp DEX seperti Hyperliquid menyelesaikan funding setiap jam, sementara exchange lain umumnya setiap 8 jam. Harga mengacu pada oracle, dan aturan likuidasinya berbeda per platform.","Kelebihannya adalah transparansi posisi dan dana di blockchain serta tidak bergantung pada kustodian. Risikonya meliputi bug smart contract atau bridge, manipulasi oracle pada pasar kecil, likuiditas yang lebih tipis untuk koin kecil, dan keamanan dompet yang sepenuhnya tanggung jawab Anda."],"example":"Misalnya Anda menyetor 2.000 USDC dan membuka long BTC dengan leverage 5x, sehingga nilai posisi 10.000 USDC saat BTC 100.000 USDC. Jika BTC naik 3%, posisi untung sekitar 300 USDC, atau 15% dari margin, sebelum fee dan funding. Jika BTC turun, kerugian 5 kali lebih cepat terhadap margin. Likuidasi terjadi sebelum harga turun penuh 20%, karena posisi harus tetap menyisakan margin pemeliharaan.","mistakes":["Mengira perp DEX tidak memiliki risiko likuidasi karena berjalan on-chain.","Menyamakan jadwal funding perp DEX dengan exchange terpusat tanpa memeriksa spesifikasi kontrak.","Membuka posisi besar di pasar kecil dengan likuiditas tipis dan oracle yang mudah dimanipulasi."],"faq":[{"q":"Apa beda perp DEX dan futures di exchange terpusat?","a":"Produknya serupa, tetapi di perp DEX Anda bertransaksi dari dompet sendiri dan posisi tercatat di blockchain. Di exchange terpusat, dana disimpan dan dikelola oleh exchange."},{"q":"Apakah perp DEX memerlukan KYC?","a":"Banyak perp DEX hanya memerlukan koneksi dompet. Namun beberapa antarmuka membatasi wilayah tertentu, dan aturan derivatif kripto berbeda di setiap negara."}],"title":"Apa itu perp DEX? Arti perpetual on-chain","description":"Pelajari arti perp DEX, contoh seperti Hyperliquid, cara kerja leverage dan funding on-chain, serta risikonya dibanding exchange terpusat.","related":[["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["dex","DEX (decentralized exchange)","DEX adalah exchange kripto yang berjalan di smart contract, di mana Anda bertransaksi langsung dari dompet sendiri tanpa menyetor dana ke perusahaan perantara."],["funding-rate","Funding rate","Funding rate adalah pembayaran berkala antara trader posisi long dan short di kontrak perpetual yang menjaga harga kontrak tetap dekat dengan harga spot."],["non-custodial-wallet","Dompet non-kustodian (self-custody wallet)","Dompet non-kustodian adalah dompet kripto di mana hanya Anda yang memegang private key, sehingga tidak ada pihak lain yang bisa memindahkan, membekukan, atau memulihkan aset Anda."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"id","term":"Copy trading","aka":["copy trade","trading salin","salin trader"],"short":"Copy trading adalah fitur bursa yang otomatis meniru posisi trader lain, yang biasa disebut lead trader, ke akun Anda sesuai modal dan pengaturan yang Anda pilih.","body":["Bursa seperti OKX, Bybit, dan Bitget menyediakan copy trading untuk spot maupun futures. Anda memilih trader dari daftar, menentukan modal, lalu setiap kali trader itu membuka atau menutup posisi, sistem melakukan hal serupa di akun Anda. Biasanya lead trader mendapat bagian keuntungan dari pengikut, misalnya persentase tertentu dari profit.",["Ada dua cara umum menyalin: rasio tetap, di mana ",["ukuran posisi","position-sizing"]," mengikuti proporsi modal trader, dan jumlah tetap per order. Anda juga bisa mengatur ",["leverage","leverage"]," maksimal, ",["stop loss","stop-loss"]," total, dan batas modal per posisi. Nama dan pilihan fitur berbeda di setiap bursa."],["Risiko utamanya: kinerja masa lalu tidak menjamin hasil berikutnya, statistik ROI tinggi bisa berasal dari leverage besar dan periode pendek, dan harga eksekusi Anda bisa berbeda dari lead trader karena ",["slippage","slippage"],". Di futures, akun Anda tetap bisa terkena ",["likuidasi","liquidation"],"."]],"example":["Misalkan Anda menyalin seorang trader dengan modal 500 ",["USDT","usdt"],". Trader itu membuka long BTC memakai 20% modalnya dengan leverage 10x. Di akun Anda, sistem membuka posisi dengan margin 100 USDT, jadi nilai posisi 1.000 USDT. Jika BTC naik 3%, profit Anda sekitar 30 USDT, lalu jika bagi hasil 10%, Anda menyerahkan 3 USDT dan menyimpan 27. Jika BTC justru turun 8%, kerugian sekitar 80 USDT, atau 80% dari margin posisi itu, dan posisi sudah sangat dekat likuidasi."],"mistakes":["Memilih trader hanya karena ROI tinggi tanpa melihat drawdown dan lamanya riwayat.","Menyalin dengan leverage lebih tinggi dari yang sanggup Anda tanggung.","Tidak memasang batas kerugian total untuk modal copy trading."],"faq":[{"q":"Apakah copy trading pasti untung?","a":"Tidak. Anda menanggung kerugian yang sama seperti trader yang Anda salin, ditambah perbedaan harga eksekusi dan biaya bagi hasil saat profit."},{"q":"Bagaimana memilih lead trader?","a":"Lihat riwayat minimal beberapa bulan, drawdown maksimal, leverage rata-rata, dan jumlah pengikut yang bertahan. ROI tinggi dalam waktu singkat sering berarti risiko tinggi."}],"title":"Apa itu copy trading kripto? Cara kerja dan risikonya","description":"Pelajari cara kerja copy trading di bursa kripto, bagi hasil lead trader, pengaturan penting, dan risiko likuidasi.","related":[["perpetual-futures","Kontrak berjangka perpetual (perpetual futures)","Kontrak berjangka perpetual adalah kontrak futures tanpa tanggal jatuh tempo yang harganya dijaga tetap dekat dengan harga spot melalui pembayaran funding rate berkala antara posisi long dan short."],["leverage","Leverage (daya ungkit)","Leverage adalah fitur yang memungkinkan Anda membuka posisi lebih besar dari modal yang disetor, misalnya 10x berarti margin 100 USDT mengendalikan posisi senilai 1.000 USDT."],["risk-reward-ratio","Rasio risk-reward (risk-reward ratio)","Rasio risk-reward adalah perbandingan antara potensi kerugian sebuah trade (jarak ke stop loss) dan potensi keuntungannya (jarak ke take profit), misalnya 1:2."],["grid-trading-bot","Grid trading bot (bot grid)","Grid trading bot adalah bot otomatis yang memasang serangkaian order beli dan jual di beberapa tingkat harga dalam satu rentang, untuk mengambil untung kecil berulang saat harga naik turun."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
